async function runBatch6() {
    loadEnv();
    const uri = process.env.NEO4J_URI;
    const user = process.env.NEO4J_USERNAME;
    const password = process.env.NEO4J_PASSWORD;
    if (!uri || !user || !password) {
        throw new Error("Missing Neo4j connection credentials in environment.");
    }
    console.log(`Connecting to Neo4j at ${uri}...`);
    const driver = neo4j.driver(uri, neo4j.auth.basic(user, password));
    const session = driver.session();
    try {
        console.log(`=== INGESTING BATCH 6 (Entries 191-240, Size: ${batch6Data.length}) ===`);
        // 1. Ensure Series nodes exist
        const seriesList = [
            "深度画像与本命天赋",
            "亲密关系与情感解构",
            "社交互动与冲突",
            "职业发展与成长",
            "进阶提升与成长指南",
        ];
        for (const sName of seriesList) {
            await session.run(`MERGE (s:Series {name: $name})
         ON CREATE SET s.createdAt = datetime()
         RETURN s`, { name: sName });
        }
        console.log(`Ensured ${seriesList.length} Series nodes.`);
        // 2. Insert Batch 6 Insights
        for (const entry of batch6Data) {
            const params = {
                id: entry.id,
                sourceIndex: entry.sourceIndex,
                title: entry.title,
                archetype: entry.archetype || null,
                analogy: entry.analogy || null,
                coreParadox: entry.coreParadox || null,
                energyMechanism: entry.energyMechanism || null,
                quote: entry.quote,
                cleanedText: entry.cleanedText,
                actionableAdvice: entry.actionableAdvice,
                seriesName: entry.series,
            };
            await session.run(`MERGE (i:Insight {id: $id})
         SET i.sourceIndex = $sourceIndex,
             i.title = $title,
             i.archetype = $archetype,
             i.analogy = $analogy,
             i.coreParadox = $coreParadox,
             i.energyMechanism = $energyMechanism,
             i.quote = $quote,
             i.cleanedText = $cleanedText,
             i.actionableAdvice = $actionableAdvice,
             i.updatedAt = datetime()
         WITH i
         MATCH (s:Series {name: $seriesName})
         MERGE (i)-[:BELONGS_TO_SERIES]->(s)
         RETURN i.id`, params);
            // Connect to associated MBTI Types
            for (const typeCode of entry.types) {
                if (typeCode === "ALL")
                    continue;
                await session.run(`MATCH (t:Type {code: $typeCode})
           MATCH (i:Insight {id: $id})
           MERGE (t)-[r:HAS_INSIGHT]->(i)
           ON CREATE SET r.createdAt = datetime()
           RETURN count(r)`, { typeCode, id: entry.id });
            }
        }
        console.log(`Ingested ${batch6Data.length} Insight nodes and Type linkages.`);
        // 3. Update Type core properties for ENFJ, ENFP, ENTP, ESFJ
        console.log("Updating Type properties for ENFJ, ENFP, ENTP, ESFJ...");
        await session.run(`MATCH (t:Type {code: 'ENFJ'})
       SET t.archetype = '八边形战士 / 社群地下领袖 / 传国玉玺配件',
           t.vividAnalogy = '手握传国玉玺的大树型领袖；早中晚期演进巨大，晚期将所有颜色熔炼为灰色的人类终极观察员；警惕救世主情结',
           t.coreParadox = '对全世界春风化雨面面俱到，常被误为中央空调，实则关照深度绝不共享；过度利他导致陷入拯救低能量群体的鬼打墙',
           t.energyModel = '主导Fe博爱社群共鸣 + 辅助Ni远期宏大愿景 + 第三Se活在当下 + 劣势Ti讲理短板易受情绪反噬'`);
        await session.run(`MATCH (t:Type {code: 'ENFP'})
       SET t.archetype = '烟花造梦师 / 引导型纯爱小孩 / 快乐小狗',
           t.vividAnalogy = '百株烟花同时盛放的庆典；用最纯粹的真诚和夸张情绪价值对抗世俗冰冷；心碎时只需一块小蛋糕就能回血',
           t.coreParadox = '表面社交花蝴蝶人缘爆棚，真心好友寥寥无几；恋爱浓度百分之一千，但遭遇欺骗与打压会毫无留恋绝决撤离',
           t.energyModel = '主导Ne海量发散灵感 + 辅助Fi真挚纯粹共情 + 第三Te突击搞钱执行 + 劣势Si厌恶规训经验'`);
        await session.run(`MATCH (t:Type {code: 'ENTP'})
       SET t.archetype = '星图织网者 / 破局鬼才 / 恶趣味辩论狂',
       t.vividAnalogy = '点亮满天繁星的解构大师；看似东一榔头西一棒槌，点线成网瞬间顿悟；用抽象幽默消解严肃沉重',
       t.coreParadox = '平时嘴比钢铁硬、创飞所有人为乐，遇到深爱之人却主动封印理性Ti，展示后知后觉的笨拙温柔',
       t.energyModel = '主导Ne打破陈规自由探索 + 辅助Ti构建底层逻辑模型 + 第三Fe逐渐习得共情体恤 + 劣势Si抗拒机械重复'`);
        await session.run(`MATCH (t:Type {code: 'ESFJ'})
       SET t.archetype = '人间春风 / 社群大总管 / 海绵宝宝同款',
       t.vividAnalogy = '走在人群中的贴心雷达；大脑硬盘记满所有人的口味偏好；有他在的地方没有战火只有温馨团建',
       t.coreParadox = '倾尽毕生心血为他人奉献，将他人的满意视作最高价值，却在缺乏关注与存在感时深陷被抛弃焦虑',
       t.energyModel = '主导Fe感知体恤全员需求 + 辅助Si经验积累与细节记忆 + 第三Ne偶尔脑洞发散 + 劣势Ti讲道理非其所长'`);
        // 4. Final DB Stats
        const countRes = await session.run(`
      MATCH (n)
      WITH count(n) AS totalNodes
      MATCH ()-[r]->()
      RETURN totalNodes, count(r) AS totalRels
    `);
        const nodeCount = countRes.records[0].get("totalNodes").toNumber();
        const relCount = countRes.records[0].get("totalRels").toNumber();
        console.log(`\n=== BATCH 6 (50 entries) INGESTION COMPLETE ===`);
        console.log(`Live Neo4j AuraDB Stats: ${nodeCount} Nodes, ${relCount} Relationships.`);
    }
    finally {
        await session.close();
        await driver.close();
    }
}
runBatch6().catch((err) => {
    console.error("Batch 6 ingestion failed:", err);
    process.exit(1);
});
